            (plan.summary.itemsAnalyzed || 0) +
            ' ' +
            plural(plan.summary.itemsAnalyzed || 0, 'товар', 'товари', 'товарів') +
            ' · <b>' +
            money(originalTotal) +
            '</b>\n\n' +
            'Дешевших аналогів, які зберігають суть покупки, не знайшов.\n\n' +
            RULE + '\n' + statsLines(plan.summary, 0, plan.mode).join('\n');
