            linkTo(clipped[index], getProductUrl({ slug: r.originalSlug })) + '\n' +
            '      ➜ ' + linkTo(clipped[replacements.length + index], getProductUrl({ slug: r.replacementSlug })) + '\n' +
            '      ' + priceLine + '\n' +
            '      ' + facts.join(' · ') + '\n';
