function money(value) {
    const amount = Number(value) || 0;
    const fixed = Math.abs(amount).toFixed(2);
    const parts = fixed.split('.');
    const grouped = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, NBSP);
    return (amount < 0 ? '−' : '') + grouped + ',' + parts[1] + NBSP + '₴';
