function defaultSelection(replacements) {
    return replacements.map((r, i) => i).filter((i) => replacements[i].confident);
}
/**
 * The cart as it stands right now — a statement, not a proposal.
 *
 * Fifteen lines of a real cart are what this screen has to survive, and the
 * first version did not. Three things fixed it:
 *
 *   - **A fixed rhythm.** Every item is exactly two lines, because a name that
 *     wraps onto a third one collides with the price beneath it and the eye
 *     loses the column. Long names are clipped at a word; the full name is a tap
 *     away in the Silpo app.
 *   - **One bold element per item.** The price is what the guest scans for, so
 *     it is the only weight on the line and the rest recedes around it.
 *   - **A price tag, not a formula.** "🎁 −100,00 ₴" needed decoding: minus what,
 *     off what? The line now reads the way a shelf label does — the price you
 *     pay, then the price you would have paid, struck out. Nobody has to be told
 *     what that means.
 */
function buildCartCard(lines, total, extras = {}) {
    // Thirty items was the only limit here, and it was the wrong kind of limit.
    // Thirty rows of the longest names Silpo writes — «Оселедець Norsk
    // Delikatesse норвезький молодий слабосолоний, філе в упаковці», kept
    // unclipped because four of them collide — comes to 4239 characters, and
    // Telegram refuses anything over 4096 outright. The guest would have seen no
    // cart at all rather than a shortened one. A character budget below does the
    // real work; this cap only stops the loop early on an enormous basket.
    const LIMIT = 30;
    const shown = lines.slice(0, LIMIT);
    let text = '🛒 <b>Ваш кошик</b>\n' +
        lines.length + ' ' + plural(lines.length, 'товар', 'товари', 'товарів') +
        ' · <b>' + money(total) + '</b>\n' +
        RULE + '\n';
    const names = clipAll(shown.map((item) => item.name), 38);
    const items = shown.map((item, index) => {
        // Price first and bold, old price struck out right after it: the two
        // numbers explain each other, so neither needs a label.
        const meta = [b(money(item.price))];
        if (item.oldPrice && item.oldPrice > item.price)
            meta.push(s(money(item.oldPrice)));
        const tail = [];
        if (item.quantity && item.quantity > 1)
            tail.push('× ' + item.quantity);
        if (item.ratio)
            tail.push(esc(item.ratio));
        return (
        // The name carries the link; the price line under it stays plain, so the
        // tap target is the product and nothing else on the row.
        (index + 1) + '. ' + linkTo(names[index], getProductUrl(item)) + '\n     ' +
            meta.join(' ') + (tail.length ? ' · ' + tail.join(' · ') : ''));
    });
    // The tail is built first so the budget knows what it has to leave room for.
    // Discounts, bonuses and the checkout-blocking slot warning are the part a
    // guest must not lose to a long list of things they already know they bought.
    const notes = [];
    if (extras.discount && extras.discount > 0)
        notes.push('🎁 Знижок уже враховано · <b>' + money(extras.discount) + '</b>');
    if (extras.bonusAvailable && extras.bonusAvailable > 0)
        notes.push('💳 Балабонуси · ' + money(extras.bonusAvailable));
    // There used to be a third line here: «⏰ Слот доставки протух — оберіть новий
    // у застосунку, інакше кошик не оформиться». It is gone, and the reason is
    // not that it was untrue.
    //
    // The test for it is `timeslotStart < now`, which is satisfied for everybody
    // who filled a basket yesterday — and an expired slot is not a broken state,
    // it is an unfinished checkout. Picking a slot *is* part of checking out, and
    // the Silpo app asks for one at the till. So the bot was telling almost every
    // guest, almost every time, that they had not finished ordering yet, which
    // they knew. A warning that is nearly always true stops being a warning and
    // becomes the thing the eye learns to skip — taking the discount and bonus
    // lines above it along.
    //
    // The run itself is unaffected: `Optimize Cart` fetches a fresh slot before
    // it asks Silpo anything, precisely so a stale one cannot skew availability.
    const tail = notes.length ? '\n' + RULE + '\n' + notes.join('\n') : '';
    // A blank line between items, the same as on the selection card and for the
    // same reason. Ten two-line blocks stacked without a gap read as twenty lines
    // of alternating name and price, and the eye has to use the leading digit to
    // find where each item starts. The gap does the grouping instead, and it is
    // what makes a price sit under its own name rather than float between two.
    const BUDGET = 3900;
    let kept = 0;
    for (const item of items) {
        const next = (kept ? '\n\n' : '') + item;
        // 90 characters held back for the «…і ще N позицій» line this may need.
        if (budgetLength(text) + budgetLength(next) + tail.length + 90 > BUDGET)
            break;
        text += next;
        kept++;
    }
    const hidden = lines.length - kept;
    if (hidden > 0) {
        text += '\n\n<i>…і ще ' + hidden + ' ' + plural(hidden, 'позиція', 'позиції', 'позицій') + '.</i>';
    }
    text += tail;
    return { text, keyboard: [[{ text: BUTTON.optimize, callback_data: 'optimize:' }]] };
}
/* --------------------------------------------------------- selection card */
/**
 * The main screen: what the run found, and what the guest can do about it.
 *
 * Structure, in order of what a person needs to decide:
 *   1. the saving, as a headline number;
 *   2. before → after, one line;
 *   3. the replacements, three lines each;
 *   4. everything else — caveats, bonuses — as quiet trailing notes.
 *
 * The per-item caveats that used to sit here (pack size, brand hint) moved into
 * a single trailing sentence and the «Деталі» screen: they matter, but not while
 * the guest is ticking boxes.
 */
function buildSelectionCard(plan, selected) {
    const replacements = plan.replacements || [];
    const originalTotal = plan.summary.originalTotal;
    if (!replacements.length) {
        let text = '✅ <b>Кошик уже оптимальний</b>\n\n' +
            (plan.summary.itemsAnalyzed || 0) +
            ' ' +
            plural(plan.summary.itemsAnalyzed || 0, 'товар', 'товари', 'товарів') +
            ' · <b>' +
            money(originalTotal) +
            '</b>\n\n' +
            'Дешевших аналогів, які зберігають суть покупки, не знайшов.\n\n' +
            RULE + '\n' + statsLines(plan.summary, 0, plan.mode).join('\n');
        // The stale-slot caveat is gone from here too, for the same reason: the run
        // used a fresh slot, so "availability may have been misread" was not what
        // happened. An empty result means no candidate survived the gate and the
        // model — saying otherwise sent the guest to fix something unrelated.
        return { text, keyboard: [] };
    }
    const chosen = replacements.filter((r, i) => selected.indexOf(i) !== -1);
    const saving = chosen.reduce((sum, r) => sum + r.saving, 0);
    const share = percent(saving, originalTotal);
    // Nothing ticked means nothing cleared the confidence bar. The headline then
    // states what is on offer instead of a promise of zero, and the total below
    // it is the cart as it stands — because that is what it would stay.
    const possible = replacements.reduce((sum, r) => sum + r.saving, 0);
    let text = !chosen.length
        ? '💰 <b>Можлива економія ' + money(possible) + '</b>\n' +
            'Жодну заміну не ввімкнено — увімкніть ті, з якими згодні.\n' +
            RULE + '\n'
        : '💰 <b>Заощадите ' + money(saving) + '</b>\n' +
            'Кошик ' + money(originalTotal) + ' → ' + b(money(originalTotal - saving)) +
            (share ? ' · −' + share : '') + '\n' +
            RULE + '\n';
    // Both names are clipped against one list, originals and replacements
    // together: a replacement is usually the same product from another brand, so
    // «Напій … зі смаком лимона» and «Напій … Малина-Лаванда» collide exactly
    // where it matters, and the guest is left comparing two identical rows.
    const clipped = clipAll(replacements.map((r) => r.originalName).concat(replacements.map((r) => r.replacementName)), 34);
    // Each replacement is built twice — with its reason and without — because the
    // reason is the first thing to give up when the message runs out of room.
    // Telegram rejects anything over 4096 characters outright, and a cart with
    // fifteen replacements reaches that: the card had no budget at all before, so
    // a large basket would simply have failed to send.
    const blocks = replacements.map((r, index) => {
        const on = selected.indexOf(index) !== -1;
        // The old line was «33,99 ₴ → 19,99 ₴ · −14,00 ₴ · 🎁 акція»: the third
        // number restated the first two and read as a third price. Now the prices
        // sit on the line of the product they belong to, the new one struck through
        // the old the way a price tag does, and the only bare number left is the
        // saving — which says «економія» beside it.
        const priceLine = s(money(r.originalPrice)) + ' → ' + b(money(r.replacementPrice));
        // Facts about the product, and nothing else.
        //
        // A per-row marker for the cautious lines lived here through two wordings —
        // «менш впевнено», then «не певен» — and both failed for the same reason,
        // which was never the wording. It was a report on the bot's own state,
        // parked in a list of things that are true about the goods, so it read as a
        // third product attribute beside the saving and the promotion.
        //
        // Nothing was lost by deleting it. The empty ☐ already says the line is off;
        // the 💬 line under it already says what the doubt is about, in terms of the
        // product («зовсім інший смак»), which is what a person can actually act on.
        // What the marker was really carrying — *why* some boxes start empty —
        // belongs once under the list, with the rest of the instructions.
        const facts = ['💰 економія ' + money(r.saving)];
        if (r.onPromotion)
            facts.push('за акцією');
        const head = (on ? ON : OFF) + ' ' + b(index + 1 + '.') + ' ' +
            linkTo(clipped[index], getProductUrl({ slug: r.originalSlug })) + '\n' +
            '      ➜ ' + linkTo(clipped[replacements.length + index], getProductUrl({ slug: r.replacementSlug })) + '\n' +
            '      ' + priceLine + '\n' +
            '      ' + facts.join(' · ') + '\n';
        // The reason answers the question the guest actually has in front of a
        // swap — why is this the same purchase — and it is the model's own words
        // about this pair, not a template. The brand moved to «Деталі» to make room:
        // it matters when blocking a brand, not when deciding one swap.
        return { head, reason: r.aiReason ? '      💬 ' + i(esc(r.aiReason)) + '\n' : '' };
    });
    // The legend appears only when it has something to explain. On a card where
    // every line is ticked it would be answering a question nobody asked, and
    // each glyph needs its own line — two emoji on one line is the point where a
    // screen starts looking like a toy.
    const legend = replacements.some((r) => !r.confident)
        ? '✅ — впевнений, що це та сама покупка\n' +
            '☐ — тут вирішувати вам: подивіться, що я написав під ціною\n\n'
        : '';
    // Three things, not one paragraph: what the buttons do, what the two glyphs
    // mean, what to press when you are finished. Run together they were four
    // consecutive lines of instruction under four consecutive lines of statistics,
    // and the eye had nothing to hold on to — the blank lines are what make the
    // legend read as a legend rather than as two more sentences.
    const footer = RULE + '\n' +
        statsLines(plan.summary, replacements.length, plan.mode).join('\n') + '\n' +
        RULE + '\n\n' +
        'ℹ️ Кнопки під повідомленням вмикають і вимикають заміни.\n\n' +
        legend +
        'Натисніть ' + b('«Застосувати»') + ', коли позначите потрібне.\n';
    // A blank line between items, and it is not decoration.
    //
    // Four indented lines under a heading is a block; two such blocks with
    // nothing between them is eight lines of near-identical shape, and the only
    // thing marking where one product ends and the next begins is the ✅ or ☐ at
    // the far left. The eye has to go back to the margin and count. One empty
    // line does what a paragraph break does anywhere else, and it costs one
    // character per item against a budget that gives up reasons first.
    const GAP = '\n';
    // 3600 rather than 4096: the notes, the bonus line and the slot caveat are
    // still to come, and they are the part a guest must not lose.
    const LIMIT = 3600;
    const withReasons = blocks.reduce((sum, blk) => sum + budgetLength(blk.head) + blk.reason.length + GAP.length, 0);
    const withReason = text.length + withReasons + footer.length <= LIMIT;
    let shown = 0;
    for (const block of blocks) {
        const next = block.head + (withReason ? block.reason : '') + GAP;
        if (budgetLength(text) + budgetLength(next) + footer.length > LIMIT)
            break;
        text += next;
        shown++;
    }
    if (shown < blocks.length) {
        text += '<i>…і ще ' + (blocks.length - shown) + ' ' +
            plural(blocks.length - shown, 'заміна', 'заміни', 'замін') + ' — у «Деталях».</i>\n';
    }
    // «Торкніться позначки» named nothing the guest can see: the ✅ in the text is
    // not tappable, the buttons under the message are. Say which, and say what
    // happens after — the instruction is useless without the step it leads to.
    text += footer;
    // No caveats left here, and the one that used to be is worth recording.
    //
    // «⏰ Слот доставки протух — наявність може відрізнятися» rode on every result
    // whose cart had a stale slot, and it was close to untrue. The analysis does
    // not run against the stale slot: `Optimize Cart` fetches a fresh one from
    // `get_time_slots` and asks every question against that, precisely so
    // availability is read correctly. The warning described a problem the
    // pipeline had already worked around, on a screen where the guest could do
    // nothing about it.
    //
    // Where it belongs is the cart screen, which says the actionable thing
    // instead — «оберіть новий у застосунку, інакше кошик не оформиться». A slot
    // is a checkout problem, not an optimization problem.
    const notes = [];
    // There used to be an unconditional note here explaining that Silpo does not
    // expose pack size in search, so it could only be checked from the cart. That
    // stopped being true in silpo-mcp-service v1.108.0: `displayRatio` is present
    // on every candidate (measured 361 of 361), so pack size is compared before a
    // replacement is ever proposed. A caveat that no longer applies is worse than
    // none — the rare line that genuinely could not be compared says so on its own
    // row instead.
    // The bonus line moved into the stats block above, beside the other money the
    // guest has but this run did not produce. It used to sit here on its own,
    // where it read as part of the saving rather than as something separate.
    if (notes.length)
        text += '\n' + notes.join('\n\n');
    // One row per replacement, and the second button on it is deliberate: a row of
    // its own would double the keyboard on a sixteen-line card, and a single
    // global «показати альтернативи» would open a list of everything with no way
    // to tell which product it belonged to. Beside the checkbox it inherits the
    // row's subject, which is the product named on the same line.
    //
    // It appears only where there is something behind it — a button that opens an
    // empty screen is worse than no button.
    const keyboard = replacements.map((r, i) => {
        const row = [
            {
                text: (selected.indexOf(i) !== -1 ? ON : OFF) + ' ' + (i + 1) + '. ' + trim(r.originalName, 26),
                callback_data: 't:' + plan.planId + ':' + i,
            },
        ];
        if (offerableAlternates(r).length) {
            row.push({ text: BUTTON.alternates, callback_data: 'alt:' + plan.planId + ':' + i });
        }
        return row;
    });
    keyboard.push([
        { text: BUTTON.apply + ' · ' + chosen.length, callback_data: 'apply:' + plan.planId },
        { text: BUTTON.details, callback_data: 'details:' + plan.planId },
    ]);
    keyboard.push([{ text: BUTTON.cancel, callback_data: 'cancel:' + plan.planId }]);
    return { text, keyboard };
}
/**
 * The runners-up this guest may actually be shown.
 *
 * `alternates` is the complete, ranked list the run confirmed, and apply-time
 * fallback needs all of it. What may be *offered* is narrower: working rule 3d
 * says a candidate below `minConfidence` is not put in front of anybody, and the
 * engine marks that with `offerable` where the confidence bars live. A plan
 * stored before the field existed carries none, and those are shown — they were
 * confirmed by the same pipeline.
 */
function offerableAlternates(replacement) {
    return (replacement.alternates || []).filter((a) => a && a.offerable !== false);
}
/* ------------------------------------------------------- alternatives view */
/**
 * One line's runners-up, and nothing else on the screen.
 *
 * The card stays a list of decisions; this is the one place a guest is comparing
 * products, so it can afford three lines each — the original for reference, what
 * is chosen now, and what else there is. Everything on it was already confirmed
 * during the run: no search runs, no model is called, nothing is recomputed.
 *
 * The rhythm rule from the card applies here too — every option is exactly two
 * lines plus an optional reason, so two prices sit in the same column.
 */
function buildAlternativesCard(plan, index, notice) {
    const replacements = plan.replacements || [];
    const replacement = replacements[index];
    const back = [[{ text: BUTTON.back, callback_data: 'alt:' + plan.planId }]];
    // A stale keyboard from a card that has since been redrawn. Say so plainly and
    // give the way back rather than an empty screen.
    if (!replacement) {
        return { text: '🔄 <b>Інші варіанти</b>\n\nЦя заміна вже не в плані — поверніться до списку.', keyboard: back };
    }
    // Cheapest first, defensively. The stored order is the run's ranking, and the
    // head of it is whatever was demoted the last time the guest switched this
    // line — which is a judgement about quality, not about price. A guest reading
    // a short list of prices expects them to descend from the best deal.
    // Display only: `alternates` keeps its ranking, because apply-time fallback
    // reads that order and the buttons carry each option's index in it.
    const options = offerableAlternates(replacement).slice().sort((a, b) => a.price - b.price);
    let text = '🔄 <b>Інші варіанти</b>\n' + RULE + '\n\n';
    if (notice)
        text += i(esc(notice)) + '\n\n';
    text +=
        productLink(replacement.originalName, { slug: replacement.originalSlug }) + '\n' +
            s(money(replacement.originalPrice)) +
            (replacement.quantity && replacement.quantity > 1 ? ' × ' + replacement.quantity : '') + '\n\n' +
            'Зараз обрано:\n' +
            productLink(replacement.replacementName, { slug: replacement.replacementSlug }) + '\n' +
            b(money(replacement.replacementPrice)) + ' · економія ' + money(replacement.saving) + '\n';
    if (!options.length) {
        text += '\n' + RULE + '\n\nІнших підтверджених варіантів для цієї позиції немає.';
        return { text, keyboard: back };
    }
    text += '\n' + RULE + '\n\nІнші варіанти:\n\n';
    // Clipped against one list with the two names above them: a runner-up is
    // usually the same product from another brand, so the words that tell them
    // apart sit past any sensible cut and two rows come out identical.
    const clipped = clipAll([replacement.originalName, replacement.replacementName].concat(options.map((a) => a.name)), 34);
    options.forEach((option, position) => {
        // The figure is the one `computeSaving` produced when the run confirmed this
        // candidate, and it is the same figure `applyAlternate` will recompute from
        // the same two prices if it is picked. Nothing is multiplied on this screen.
        text +=
            b(position + 1 + '.') + ' ' + linkTo(clipped[position + 2], getProductUrl(option)) + '\n' +
                b(money(option.price)) + ' · економія ' + money(option.saving) + '\n';
        if (option.reason)
            text += '💬 ' + i(esc(option.reason)) + '\n';
        text += '\n';
    });
    text += RULE + '\nОберіть варіант кнопкою нижче — заміна оновиться у списку.';
    const keyboard = options.map((option, position) => [
        {
            text: position + 1 + '. ' + trim(option.name, 24) + ' · ' + money(option.price),
            callback_data: 'altpick:' + plan.planId + ':' + index + ':' + (replacement.alternates || []).indexOf(option),
        },
    ]);
    keyboard.push(back[0]);
    return { text, keyboard };
}
/* ------------------------------------------------------------ details view */
/**
 * The full reasoning behind each line — progressive disclosure for the card.
 *
 * This is where the per-item detail the card sheds ends up: quantity, the exact
 * percentage, the model's reason, the pack-size caveat, the brand to block.
 */
function buildDetailsCard(plan, planId) {
    const replacements = plan.replacements || [];
    const saving = plan.summary.saving || 0;
    let text = '🔍 <b>Деталі оптимізації</b>\n' +
        money(plan.summary.originalTotal) + ' → <b>' + money(plan.summary.originalTotal - saving) + '</b>' +
        ' · економія <b>' + money(saving) + '</b>\n' +
        RULE + '\n\n';
    // The details view is the one place a full product name is worth its space:
    // the guest opened it precisely to read what the card abbreviated.
    const blocks = replacements.map((r, i) => {
        const lines = [
            '<b>' + (i + 1) + '.</b> ' + productLink(r.originalName, { slug: r.originalSlug }),
            // Struck through here too, so the card and its details tell the same
            // visual story: this price is the one being left behind.
            '      ' + s(money(r.originalPrice)) + (r.quantity && r.quantity > 1 ? ' × ' + r.quantity : ''),
            '      ⬇',
            '      ' + productLink(r.replacementName, { slug: r.replacementSlug }),
            '      <b>' + money(r.replacementPrice) + '</b>' + (r.onPromotion ? ' · 🎁 акція' : ''),
            '      💰 економія ' + money(r.saving) + (r.savingPct ? ' · −' + r.savingPct + '%' : ''),
        ];
        if (r.brand)
            lines.push('      🏷 марка ' + esc(r.brand));
        if (r.aiReason)
            lines.push('      💬 <i>' + esc(r.aiReason) + '</i>');
        // The card says this in three words; here there is room to say what the
        // guest is actually being asked to do about it.
        // Here there is room to say it as a sentence, and the sentence is about the
        // guest's decision rather than about the bot's certainty.
        if (!r.confident)
            lines.push('      ⚖️ <i>не позначив — вирішіть самі, чи це та сама покупка</i>');
        // Rare now: fires when the two pack sizes are not comparable at all — a
        // count against a volume ("30шт" vs "1,5л") — not because the data is missing.
        if (r.verifySize)
            lines.push('      📦 <i>фасування не звірити — перевірю в кошику</i>');
        return lines.join('\n');
    });
    // Telegram caps a message at 4096 characters.
    const LIMIT = 3900;
    const kept = [];
    for (const block of blocks) {
        if (budgetLength(text + kept.join('\n\n') + block) > LIMIT)
            break;
        kept.push(block);
    }
