} }}];

// The Code-node sandbox is a restricted VM, not Node: there is no fetch, no URL
// and no URLSearchParams, and require() is limited to an allowlist - 'crypto'
// loads, 'url' and 'buffer' are rejected outright.
//
// Buffer is therefore taken from a real Buffer instance produced by crypto,
// which needs no module and no global.
const Buf = require('crypto').randomBytes(0).constructor;

// The node context is bound to 'this' only at the top level of a Code node;
// inside a plain function call it is undefined. Capture the helper here.
const _nodeHelpers = (function () {
  try {
    return this && this.helpers ? this.helpers : null;
  } catch (e) {
    return null;
  }
}).call(this);

function _toText(raw) {
  if (raw === undefined || raw === null) return '';
  if (typeof raw === 'string') return raw;
  if (raw.constructor === Buf) return raw.toString('utf8');
  if (raw.type === 'Buffer' && Array.isArray(raw.data)) return Buf.from(raw.data).toString('utf8');
  return JSON.stringify(raw);
}

function sleep(ms) {
  if (typeof setTimeout !== 'function') return Promise.resolve();
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function toQuery(params) {
  return Object.keys(params)
    .filter((k) => params[k] !== undefined && params[k] !== null)
    .map((k) => encodeURIComponent(k) + '=' + encodeURIComponent(params[k]))
    .join('&');
}

async function httpFetch(url, opts) {
  const method = (opts && opts.method) || 'GET';
  const headers = (opts && opts.headers) || {};
  const body = opts && opts.body;
  const wrap = (status, headerObj, text) => ({
    status,
    text,
    headers: { get: (n) => headerObj[String(n).toLowerCase()] },
  });

  // 1. Native fetch, when the runtime provides it.
  if (typeof fetch === 'function') {
    const res = await fetch(url, { method, headers, body });
    return { status: res.status, text: await res.text(), headers: { get: (n) => res.headers.get(n) } };
  }

  // 2. n8n's own HTTP helper — the transport that actually exists on Cloud.
  if (_nodeHelpers && _nodeHelpers.httpRequest) {
    try {
      const res = await _nodeHelpers.httpRequest({
        url, method, headers, body,
        json: false,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
      });
      return wrap(res.statusCode || 200, res.headers || {}, _toText(res.body));
    } catch (err) {
      // Older helpers throw on non-2xx instead of honouring
      // ignoreHttpStatusErrors. Recover the status so 401 and 429 stay visible
      // to the retry logic rather than surfacing as a generic failure.
      const response = err && err.response;
      const status = (err && (err.statusCode || err.httpCode))
        || (response && (response.statusCode || response.status));
      if (status) {
        return wrap(Number(status), (response && response.headers) || {}, _toText(response && response.body));
      }
      throw err;
    }
  }

  // 3. Raw https module, if the allowlist happens to permit it.
  let https;
  try {
    https = require('https');
  } catch (e) {
    throw new Error('NO_HTTP_TRANSPORT: sandbox has no fetch, no this.helpers.httpRequest and no https module');
  }
  // Parsed with string ops rather than a regex: escaping a regex through this
  // template literal is how the previous build silently produced a comment.
  const withoutScheme = String(url).replace('https://', '').replace('http://', '');
  const firstSlash = withoutScheme.indexOf('/');
  const hostPort = firstSlash === -1 ? withoutScheme : withoutScheme.slice(0, firstSlash);
  const path = firstSlash === -1 ? '/' : withoutScheme.slice(firstSlash);
  const colon = hostPort.indexOf(':');
  const hostname = colon === -1 ? hostPort : hostPort.slice(0, colon);
  const port = colon === -1 ? 443 : Number(hostPort.slice(colon + 1));

  return await new Promise((resolve, reject) => {
    const req = https.request(
      { hostname, port, path, method, headers },
      (res) => {
        let data = '';
        res.setEncoding('utf8');
        res.on('data', (chunk) => { data += chunk; });
        res.on('end', () => resolve(wrap(res.statusCode, res.headers || {}, data)));
      },
    );
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

const MCP_URL = 'https://mcp.silpo.ua/mcp';
const TOKEN_URL = 'https://mcp.silpo.ua/token';
const PROTOCOL_VERSION = '2025-06-18';

function createMcp(session) {
  let accessToken = session.access_token;
  let refreshed = null;
  let initialized = false;

  async function refresh() {
    const res = await httpFetch(TOKEN_URL, {
      method: 'POST',
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: toQuery({
        grant_type: 'refresh_token',
        refresh_token: session.refresh_token,
        client_id: session.client_id,
        resource: MCP_URL,
      }),
    });
    if (res.status < 200 || res.status >= 300) { const e = new Error('SILPO_REAUTH_REQUIRED'); e.code = 'REAUTH'; throw e; }
    const t = JSON.parse(res.text);
    accessToken = t.access_token;
    refreshed = {
      access_token: t.access_token,
      refresh_token: t.refresh_token || session.refresh_token,
      expires_at: new Date(Date.now() + (t.expires_in || 3600) * 1000).toISOString(),
    };
    return accessToken;
  }

  async function rpc(method, params) {
    const id = Math.floor(Math.random() * 1e9);
    const send = () => httpFetch(MCP_URL, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        accept: 'application/json, text/event-stream',
        authorization: 'Bearer ' + accessToken,
        'mcp-protocol-version': PROTOCOL_VERSION,
      },
      body: JSON.stringify({ jsonrpc: '2.0', id, method, params }),
    });

    let res = await send();
    if (res.status === 401) { await refresh(); res = await send(); }
    for (let i = 0; (res.status === 429 || res.status >= 500) && i < 5; i++) {
      await sleep(Math.pow(2, i) * 1000 + Math.random() * 250);
      res = await send();
    }
    if (res.status === 403) { const e = new Error('SILPO_FORBIDDEN'); e.code = 'FORBIDDEN'; throw e; }
    if (res.status < 200 || res.status >= 300) { const e = new Error('SILPO_MCP_ERROR_' + res.status); e.code = 'MCP'; throw e; }

    const raw = res.text;
    let msg;
    if ((res.headers.get('content-type') || '').includes('text/event-stream')) {
      for (const line of raw.split('\n')) {
        if (!line.startsWith('data:')) continue;
        try { const m = JSON.parse(line.slice(5).trim()); if (m.id === id || m.error) msg = m; } catch (e) {}
      }
    } else { msg = JSON.parse(raw); }
    if (!msg) throw new Error('SILPO_EMPTY_RESPONSE');
    if (msg.error) throw new Error('SILPO_RPC_' + msg.error.code);
    return msg.result;
  }

  return {
    async call(name, args) {
      if (!initialized) {
        await rpc('initialize', {
          protocolVersion: PROTOCOL_VERSION,
          capabilities: {},
          clientInfo: { name: 'silpo-optimizer-n8n', version: '1.0.0' },
        });
        initialized = true;
      }
      const result = await rpc('tools/call', { name, arguments: args || {} });
      const textPart = (result.content || []).find(c => c.type === 'text');
      let data = result;
      if (textPart) { try { data = JSON.parse(textPart.text); } catch (e) { data = { raw: textPart.text }; } }
      if (result.isError) {
        const detail = typeof data === 'string' ? data : JSON.stringify(data);
        const e = new Error('TOOL_ERROR_' + name + ': ' + String(detail).slice(0, 300));
        e.code = 'TOOL';
        e.detail = data;
        throw e;
      }
      return data;
    },
    getRefreshed: () => refreshed,
  };
}

async function mapLimit(items, limit, fn) {
  const out = new Array(items.length);
  let cursor = 0;
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (cursor < items.length) {
      const i = cursor++;
      try { out[i] = { ok: true, value: await fn(items[i], i) }; }
      catch (e) { out[i] = { ok: false, error: e.message }; }
    }
  }));
  return out;
}


/**
 * Presentation layer — every string the guest reads, and every keyboard.
 *
 * Why a module and not strings scattered through `build.ts`: the copy was spread
 * across fourteen nodes, half of it inside TypeScript template literals where a
 * newline has to be written `\\n` and a backtick ends the literal. Nothing about
 * wording deserves that hazard. This file is inlined into the Code nodes the same
 * way `optimizer.ts` is, so the text here is ordinary source: real `\n`, real
 * apostrophes, no double escaping.
 *
 * Two consumers:
 *   - Code nodes    — the module is transpiled and prepended (see UI_MODULE).
 *   - node params   — `build.ts` imports `UI` directly for static messages.
 *
 * Design rules this file follows:
 *   - Buttons are the interface. No screen prints a command: they are registered
 *     with `setMyCommands` (npm run setup:commands) and live under Telegram's «/»
 *     menu, which is where a fallback belongs.
 *   - Emoji mark, they do not decorate: one at the head of a screen title or a
 *     section, one as a status marker on a line (🎁 promotion, 💰 saving, 💳
 *     bonuses, ⏰ expired slot, 📦 pack size). Never two in a row, never mid
 *     sentence.
 *   - Lists keep a fixed rhythm. Long product names are clipped so every item is
 *     the same height and the price column stays a column.
 *   - One bold element per line — the number the guest is scanning for.
 *   - One screen, one job. Anything that is not a daily action moves behind
 *     Settings; anything not needed to decide moves behind «Деталі».
 *
 * Language: Ukrainian, per the project rule — these are strings Silpo guests read.
 */
/* --------------------------------------------------------------- primitives */
/** Non-breaking space: keeps "1 847 ₴" from wrapping mid-number on mobile. */
const NBSP = ' ';
/**
 * Money, the way a receipt prints it: grouped thousands, decimal comma, ₴.
 *
 * The sign is rendered with U+2212 rather than a hyphen so a saving reads as a
 * minus and not as a list bullet.
 */
function money(value) {
    const amount = Number(value) || 0;
    const fixed = Math.abs(amount).toFixed(2);
    const parts = fixed.split('.');
    const grouped = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, NBSP);
    return (amount < 0 ? '−' : '') + grouped + ',' + parts[1] + NBSP + '₴';
}
/** A saving, always written as a negative delta. */
function delta(value) {
    return '−' + money(Math.abs(Number(value) || 0));
}
/** One decimal, no trailing ",0" — percentages are context, not headline. */
function percent(part, whole) {
    if (!whole)
        return '';
    const value = Math.round((part / whole) * 1000) / 10;
    return String(value).replace('.', ',') + '%';
}
/**
 * Escapes text for HTML parse mode.
 *
 * The screens are HTML rather than Markdown for one reason: `<s>` — a struck-out
 * old price says "this is a discount" the way a price tag does, with no word and
 * no symbol to decode. Legacy Markdown has no strikethrough at all.
 *
 * Escaping is also saner here. Markdown needed every `_` and `*` in a product
 * name escaped or Telegram rejected the whole message with HTTP 400; HTML needs
 * exactly these three characters, and Telegram ignores unknown tags rather than
 * refusing the send.
 */
function esc(text) {
    return String(text).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
}
/** Bold — the one number per line the eye should land on. */
function b(text) {
    return '<b>' + text + '</b>';
}
/** Italic — asides and caveats, never a fact the guest needs. */
function i(text) {
    return '<i>' + text + '</i>';
}
/** Struck out — a price that no longer applies. */
function s(text) {
    return '<s>' + text + '</s>';
}
/* ------------------------------------------------------------ product links */
/**
 * The canonical Silpo product page.
 *
 * Not guessed and not scraped. `silpo_get_product_details` returns the page
 * itself as `product.url`, and on every product checked live that value is
 * exactly this prefix plus the product's own `slug` — including «fintonic»,
 * which carries no trailing id and so proves the rule is the slug and not the
 * number at its end.
 *
 * It is built here rather than read from `product.url` because every payload
 * the bot already has carries `slug` — cart lines, search results, similar
 * products — while `url` arrives only from `get_product_details`. Reading it
 * would mean one MCP call per rendered line; building it costs none.
 */
const PRODUCT_PAGE = 'https://silpo.ua/product/';
/**
 * Silpo's slug alphabet: lowercase latin, digits, single hyphens — measured on
 * 92 of 92 slugs in a live fixture.
 *
 * Anything else is not a slug this file can vouch for, and working rule 2 says
 * what to do about it: a fabricated identifier is worse than none. A name that
 * leaked into the field, an absolute URL, an empty string — all of them give a
 * link that lands the guest on a «Resource not found» page, so they give no
 * link at all instead.
 */
const SLUG = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
/**
 * The product page for anything that carries a slug, or null.
 *
 * Never throws: an absent URL is an ordinary outcome here, not a failure, and
 * every caller renders plain text when it gets null.
 */
function getProductUrl(product) {
    const slug = product && typeof product.slug === 'string' ? product.slug.trim() : '';
    return slug && SLUG.test(slug) ? PRODUCT_PAGE + slug : null;
}
/**
 * Wraps text that has **already been escaped** — `clipAll()` escapes as it
 * clips, so its output must not go through `esc()` a second time.
 */
function linkTo(html, url) {
    return url ? '<a href="' + esc(url) + '">' + html + '</a>' : html;
}
/**
 * What Telegram actually counts against its 4096-character cap.
 *
 * The cap applies to the text *after* entities are parsed, so the markup is
 * free — and a product link is some sixty characters of href wrapped around a
 * name of thirty. Counted raw, the links halved the selection card the day they
 * were added: a sixteen-replacement plan showed fifteen rows before and eight
 * after, with the rest pushed into «Деталі» for no reason a guest could see.
 *
 * Only anchors are discounted. `<b>` and `<s>` are counted as before, on
 * purpose: that conservatism is the existing margin, and widening it would
 * change how much of every card is shown, which is not what this is for.
 */
function budgetLength(html) {
    return html.split('</a>').join('').replace(/<a href="[^"]*">/g, '').length;
}
/**
 * A product name, escaped, and clickable when the product has a slug.
 *
 * The name itself is the link: a separate «Відкрити товар» button per line
 * would put fifteen rows of chrome under a card whose buttons already mean
 * something else.
 */
function productLink(name, product) {
    return linkTo(esc(name), getProductUrl(product));
}
/** A thin rule between a summary and its breakdown. */
const RULE = '─'.repeat(14);
