/** Ukrainian has three plural forms; "12 товарів" reads wrong as "12 товар". */
function plural(count, one, few, many) {
    const n = Math.abs(count) % 100;
    if (n >= 11 && n <= 14)
        return many;
    const last = n % 10;
    if (last === 1)
        return one;
    if (last >= 2 && last <= 4)
        return few;
    return many;
}
